129 /// The listed indices an answer names, in list order. A word is a number or range counted from 1 (`3`, `1-3`) when
130 /// those rows exist, else a listed name or `ecosystem/name` id; words are separated by spaces or commas.
131 fn choices(answer: &str, items: &[Listed]) -> Result<Vec<usize>, String> {
132     let mut picked = std::collections::BTreeSet::new();
133     for word in answer
134         .split(|c: char| c == ',' || c.is_whitespace())
135         .filter(|word| !word.is_empty())
136     {
137         let shown = word.escape_debug();
138         let by_name = items.iter().position(|item| item.name == word || item.id == word);
139         let indices = match (by_name, numbered(word, items.len())) {
140             (Some(index), None | Some(Err(_))) => index..=index,
141             (Some(index), Some(Ok(range))) if range == (index..=index) => range,
142             (Some(index), Some(Ok(range))) => {
143                 let rows = range
144                     .map(|row| format!("{0}-{0}", row + 1))
145                     .collect::<Vec<_>>()
146                     .join(",");
147                 let id = items[index].id.escape_debug();
148                 return Err(format!(
149                     "`{shown}` is both a package name and a row number; type `{id}` for the package or `{rows}` for the row"
150                 ));
151             }
152             (None, Some(range)) => range?,
153             (None, None) => return Err(format!("`{shown}` is not a number, a range or a listed name")),
154         };
155         picked.extend(indices);
156     }
157     Ok(picked.into_iter().collect())
158 }
