160 /// `n` or `a-b`, counted from 1, as indices; `None` when the word is shaped like neither, `Some(Err)` when the rows are
161 /// not in the list.
162 fn numbered(word: &str, len: usize) -> Option<Result<std::ops::RangeInclusive<usize>, String>> {
163     let (first, last) = word.split_once('-').unwrap_or((word, word));
164     let digits = |text: &str| !text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit());
165     if !digits(first) || !digits(last) {
166         return None;
167     }
168     let listed = |text: &str| text.parse::<usize>().ok().filter(|number| (1..=len).contains(number));
169     Some(match (listed(first), listed(last)) {
170         (Some(low), Some(high)) if low <= high => Ok(low - 1..=high - 1),
171         (Some(_), Some(_)) => Err(format!("`{word}` runs backwards; put the lower number first")),
172         _ => Err(format!("`{word}` is not in the list (1-{len})")),
173     })
174 }
