176 /// The editor named by `$VISUAL`, else `$EDITOR`.
177 pub struct Editor {
178     variable: &'static str,
179     command: String,
180 }
181 
182 /// Why the editor could not be used; its message is the warning to print.
183 #[derive(Debug, thiserror::Error)]
184 #[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
185 pub struct EditorUnusable {
186     variable: &'static str,
187     command: String,
188     reason: String,
189 }
190 
191 impl Editor {
192     /// An empty or blank setting is unset.
193     pub fn from_env() -> Option<Self> {
194         ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
195             let command = std::env::var(variable).ok()?;
196             (!command.trim().is_empty()).then_some(Self { variable, command })
197         })
198     }
199 
200     /// `VISUAL` or `EDITOR`, whichever named it.
201     pub fn variable(&self) -> &'static str {
202         self.variable
203     }
204 
205     /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
206     /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
207     pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
208         self.try_edit().map_err(|reason| EditorUnusable {
209             variable: self.variable,
210             command: self.command,
211             reason,
212         })
213     }
214 
215     fn try_edit(&self) -> Result<Option<String>, String> {
216         let words =
217             shell_words::split(&self.command).map_err(|error| format!("it does not split into words: {error}"))?;
218         let Some((program, args)) = words.split_first() else {
219             return Err("it names no program".to_owned());
220         };
221         let failed = |error: std::io::Error| error.to_string();
222         let file = tempfile::Builder::new()
223             .prefix("callisto-")
224             .suffix(".txt")
225             .tempfile()
226             .map_err(failed)?;
227         let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
228         let status = crate::runner::child_command(program, &[], &[])
229             .args(args)
230             .arg(file.path())
231             .stdout(std::io::stderr())
232             .status()
233             .map_err(|error| format!("`{program}` did not start: {error}"))?;
234         if !status.success() {
235             return Ok(None);
236         }
237         let saved = std::fs::read(file.path()).map_err(failed)?;
238         String::from_utf8(saved)
239             .map(Some)
240             .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
241     }
242 }
