245 mod editor_owns_ctrl_c {
246     use std::sync::atomic::{AtomicBool, Ordering};
247     use std::sync::Arc;
248 
249     use signal_hook::consts::SIGINT;
250 
251     /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
252     /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
253     pub struct Guard(Arc<AtomicBool>);
254 
255     pub fn enter() -> std::io::Result<Guard> {
256         let default_action = Arc::new(AtomicBool::new(false));
257         signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
258         Ok(Guard(default_action))
259     }
260 
261     impl Drop for Guard {
262         fn drop(&mut self) {
263             self.0.store(true, Ordering::SeqCst);
264         }
265     }
266 }
267 
268 #[cfg(not(unix))]
269 mod editor_owns_ctrl_c {
270     pub struct Guard;
271 
272     pub fn enter() -> std::io::Result<Guard> {
273         Ok(Guard)
274     }
275 }
