use std::collections::HashSet;
use std::path::{Path, PathBuf};

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{
    workspace_relative, Ecosystem, ModelError, PackageId, PackageKey, PublishTarget, ReleaseTrigger, TagTemplate,
    VersionGrammar,
};

/// A package in the workspace graph.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Package {
    pub id: PackageId,
    pub manifests: Vec<ManifestDecl>,
    pub changelog: Option<PathBuf>,
    pub release_trigger: ReleaseTrigger,
    pub publish_to: Vec<PublishTarget>,
    pub tag_template: Option<TagTemplate>,
}

impl Package {
    /// The directory of the first canonical manifest; `None` only for a package without one.
    pub fn key(&self) -> Option<PackageKey> {
        let manifest = self.canonical_manifests().next()?;
        Some(PackageKey::new(manifest.path.parent().unwrap_or(Path::new(""))))
    }

    /// The id reports and diagnostics print: `ecosystem/name` for the package's primary ecosystem (the same one
    /// identity assignment promotes to), whether or not the package was ever promoted. A package with no canonical
    /// manifest keeps its id.
    pub fn canonical_id(&self) -> PackageId {
        self.canonical_manifests()
            .map(|manifest| manifest.ecosystem())
            .min_by_key(|ecosystem| ecosystem.primary_priority())
            .map_or_else(
                || self.id.clone(),
                |ecosystem| PackageId::Prefixed {
                    ecosystem,
                    name: self.id.name().to_string(),
                },
            )
    }

    pub fn canonical_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
        self.manifests.iter().filter(|m| m.role == ManifestRole::Canonical)
    }

    pub fn lockfiles(&self) -> impl Iterator<Item = &ManifestDecl> {
        self.manifests.iter().filter(|m| m.role == ManifestRole::Lockfile)
    }

    pub fn version_grammar(&self) -> Result<VersionGrammar, ModelError> {
        let grammars: Vec<_> = self
            .canonical_manifests()
            .map(|m| m.format.ecosystem().version_grammar())
            .collect();

        if grammars.is_empty() {
            return Err(ModelError::no_canonical_manifest(&self.id));
        }

        let first = grammars[0];
        if grammars.iter().any(|&g| g != first) {
            let mut unique = grammars;
            unique.sort();
            unique.dedup();
            return Err(ModelError::mixed_version_grammars(&self.id, unique));
        }
